        fn switch(&mut self, call: Call, nt: VarId, alt_id: AltId, t_data: Option<Vec<String>>) {
            if self.verbose {
                println!("switch: call={call:?}, nt={nt}, alt={alt_id}, t_data={t_data:?}");
            }
            if let Some(mut t_data) = t_data {
                self.stack_t.append(&mut t_data);
            }
            match call {
                Call::Exit => {
                    match alt_id {
                        0 => self.exit_a(),                         // a -> s p
                        1 => self.exit_s(),                         // s -> vs ns xs
                        2 => self.exit_p(),                         // p -> vp np xp
                        3 => self.exit_vs(),                        // vs -> A ivs
                        4 => self.exit_ivs(),                       // ivs -> <L> ivs B
                        5 => self.init_ivs(),                       // ivs -> <L> ε
                        6 => self.exit_ns(),                        // ns -> "A" ins
                        7 => self.exit_ins(),                       // ins -> <L> ins "B"
                        8 => self.listener.init_ins(),              // ins -> <L> ε
                        9 => self.exit_xs(),                        // xs -> A ixs
                        10 => self.exit_ixs(),                      // ixs -> <L> ixs x
                        11 => self.listener.init_ixs(),             // ixs -> <L> ε
                        12 => self.exit_vp(),                       // vp -> A ivp
                        13 |                                        // ivp -> <L> ivp B
                        14 => self.exit_ivp(alt_id),                // ivp -> <L> B
                        15 => self.exit_np(),                       // np -> "A" inp
                        16 |                                        // inp -> <L> inp "B"
                        17 => self.exit_inp(),                      // inp -> <L> "B"
                        18 => self.exit_xp(),                       // xp -> A ixp
                        19 |                                        // ixp -> <L> ixp x
                        20 => self.exit_ixp(),                      // ixp -> <L> x
                        21 => self.exit_x(),                        // x -> "X"
                        _ => panic!("unexpected exit alternative id: {alt_id}")
                    }
                }
                Call::End(terminate) => {
                    match terminate {
                        Terminate::None => {
                            let val = self.stack.pop().unwrap().get_a();
                            self.listener.exit(val);
                        }
                        Terminate::Abort | Terminate::Conclude => self.listener.abort(terminate),
                    }
                }
                _ => panic!("unexpected call {call:?}, nt {nt}, alt_id {alt_id}")
            }
            self.max_stack = std::cmp::max(self.max_stack, self.stack.len());
            if self.verbose {
                println!("> stack_t:   {}", self.stack_t.join(", "));
                println!("> stack:     {}", self.stack.iter().map(|it| format!("{it:?}")).collect::<Vec<_>>().join(", "));
            }
        }

